from sympy.core.singleton import Singleton, S
from sympy.core.numbers import oo

class Min(Singleton):
    def __new__(cls, *args):
        if not args:
            return oo
        return super().__new__(cls, *args)

class Max(Singleton):
    def __new__(cls, *args):
        if not args:
            return -oo
        return super().__new__(cls, *args)
